			check: func(t *testing.T, n ContainerNetworking) {
				if len(n.Networks) != 1 || n.Networks[0].IPv4.IsValid() || n.Networks[0].Gateway.IsValid() {
					t.Errorf("got %+v", n.Networks)
				}
			},
		},
